css:
/*mk-css*/
.pcw{display:grid;grid-template-columns:200px minmax(0,1fr);border:1px solid var(--line);border-radius:14px;overflow:hidden;background:var(--card);font-family:Inter,system-ui,var(--body);margin-block:14px;box-shadow:0 10px 30px -18px rgba(0,0,0,.35)}
.pcs{background:var(--chip);border-right:1px solid var(--line);padding:12px 10px;display:grid;gap:10px;align-content:start;font-size:.85rem;line-height:1.5}
.pcb{display:flex;align-items:center;gap:8px}.pcb i{font-style:normal;display:grid;place-items:center;width:24px;height:24px;border-radius:7px;background:var(--fg);color:var(--card);font-weight:800;font-size:13px}
.pco{display:grid;gap:2px;font-size:.72rem;color:var(--muted)}
.pco select{font:inherit;font-size:.85rem;padding:4px 6px;border:1px solid var(--line);border-radius:7px;background:var(--card);color:var(--fg)}
.pcs nav{display:grid;gap:1px}
.pcs nav span,.pcs nav a{padding:4px 8px;border-radius:7px;color:var(--muted)}
.pcs nav small{margin-top:8px;font-size:.66rem;letter-spacing:.08em;color:var(--muted);padding-inline:8px}
.pcs nav a.on{background:var(--card);color:var(--fg);font-family:var(--body);font-weight:600;text-align:right;box-shadow:inset 3px 0 0 var(--boss),0 1px 2px rgba(0,0,0,.06)}
.pcm{min-width:0;font-family:var(--body);background:var(--bg)}
.pcu{font:12px ui-monospace,monospace;color:var(--muted);border-bottom:1px solid var(--line);padding:5px 12px;overflow-wrap:anywhere;background:var(--card)}
@media (max-width:700px){.pcw{grid-template-columns:minmax(0,1fr)}.pcs{border-right:0;border-bottom:1px solid var(--line)}.pcs nav{display:flex;flex-wrap:wrap;gap:2px}.pcs nav small{width:100%;margin-top:2px}}
.am{direction:rtl;display:grid;gap:12px;padding:16px;min-width:0}
.am h3{margin:0;font-size:1.2rem}
.am-hd{display:flex;flex-wrap:wrap;justify-content:space-between;align-items:center;gap:8px}
.am-acts{display:flex;gap:6px}
.am-btn{font:inherit;font-size:13px;border:1px solid var(--line);background:var(--card);color:inherit;padding:4px 12px;border-radius:8px;cursor:pointer}
.am-btn:hover{border-color:var(--muted)}
.am-muted{color:var(--muted);font-size:12px}
.am-kpi{display:grid;grid-template-columns:repeat(auto-fit,minmax(130px,1fr));gap:8px}
.am-kpi div{background:var(--card);border:1px solid var(--line);border-radius:10px;padding:8px 12px;display:grid;gap:0}
.am-kpi b{font-size:1.25rem;line-height:1.4;font-variant-numeric:tabular-nums}
.am-kpi small{color:var(--muted);font-size:12px}
.am-kpi .bar{margin-top:4px}
.am-bar{display:flex;flex-wrap:wrap;gap:8px;align-items:center}
.am-seg{display:inline-flex;background:var(--chip);border-radius:9px;padding:2px;gap:2px}
.am-seg button{font:inherit;font-size:13px;border:0;background:transparent;color:var(--muted);padding:3px 12px;border-radius:7px;cursor:pointer}
.am-seg button[aria-pressed=true]{background:var(--card);color:var(--fg);font-weight:600;box-shadow:0 1px 3px rgba(0,0,0,.15)}
.am-srch{flex:1 1 220px;display:flex;align-items:center;gap:6px;min-width:0}
.am-srch input{font:inherit;font-size:13px;padding:5px 12px;border:1px solid var(--line);border-radius:9px;background:var(--card);color:inherit;flex:1;min-width:0}
.am-zoom{display:inline-flex;align-items:center;border:1px solid var(--line);border-radius:9px;background:var(--card);overflow:hidden}
.am-zoom button{font:inherit;font-size:13px;border:0;background:transparent;color:inherit;padding:3px 10px;cursor:pointer}
.am-zoom button+span,.am-zoom span+button{border-inline-start:1px solid var(--line)}
.am-zoom{flex-wrap:wrap}.am-zoom button+button{border-inline-start:1px solid var(--line)}
.am-zoom span{font-size:12px;padding:0 8px;min-width:46px;text-align:center;font-variant-numeric:tabular-nums}
.am-chips{display:flex;flex-wrap:wrap;gap:6px}
.am-chips button{font:inherit;font-size:12px;display:inline-flex;align-items:center;gap:6px;border:1px solid var(--line);background:var(--card);color:inherit;border-radius:999px;padding:1px 10px;cursor:pointer}
.am-chips button i{width:8px;height:8px;border-radius:50%;background:var(--cc)}
.am-chips button[aria-pressed=false]{opacity:.45}
.am-chips button.all{color:var(--muted)}
.am-body{display:grid;grid-template-columns:minmax(0,1fr);gap:12px;align-items:start}
.am-body.has{grid-template-columns:minmax(0,1fr) 280px}
@media (max-width:900px){.am-body.has{grid-template-columns:minmax(0,1fr)}.am-drw{order:-1}}
.am-view{overflow:auto;max-height:78vh;min-height:320px;border:1px solid var(--line);border-radius:12px;padding:18px;background:var(--card);background-image:radial-gradient(var(--line) 1px,transparent 1px);background-size:18px 18px}
.am-in{width:max-content;min-width:100%}
.am-in.ls{width:auto;min-width:0}
.am-mn .am-av i,.am-pl .am-av i,.am-tb .am-av i{display:none}
.am-oc,.am-oc ul{list-style:none;margin:0;padding:0;display:flex;justify-content:center}
.am-oc ul{padding-top:20px;position:relative}
.am-oc li{position:relative;padding:20px 6px 0;display:flex;flex-direction:column;align-items:center}
.am-oc>li{padding-top:0}
.am-oc ul::before{content:"";position:absolute;top:0;left:50%;height:20px;border-left:1.5px solid var(--line)}
.am-oc ul>li::before,.am-oc ul>li::after{content:"";position:absolute;top:0;width:50%;height:20px;border-top:1.5px solid var(--line)}
.am-oc ul>li::before{right:50%;border-right:1.5px solid var(--line)}
.am-oc ul>li::after{left:50%}
.am-oc ul>li:first-child::after,.am-oc ul>li:last-child::before{border-top:0}
.am-oc ul>li:only-child::after{display:none}
.am-oc ul>li:only-child::before{border-top:0}
.am-oc ul>li:first-child::before{border-radius:0 10px 0 0}
.am-cd{font:inherit;position:relative;width:184px;border:1px solid var(--line);background:var(--card);color:inherit;border-radius:12px;padding:10px 10px 8px;text-align:right;display:grid;grid-template-columns:auto minmax(0,1fr);gap:2px 8px;align-items:center;cursor:pointer;box-shadow:0 1px 2px rgba(0,0,0,.06);transition:box-shadow .15s,transform .15s}
.am-cd:hover{box-shadow:0 6px 16px -6px rgba(0,0,0,.25);transform:translateY(-1px)}
.am-cd::before{content:"";position:absolute;inset:0 0 auto 0;height:3px;border-radius:12px 12px 0 0;background:var(--cc)}
.am-av{grid-row:span 2;width:36px;height:36px;border-radius:50%;display:grid;place-items:center;font:700 13px/1 Inter,system-ui,sans-serif;color:#fff;background:var(--cc);position:relative;letter-spacing:.02em}
.am-av.lg{width:56px;height:56px;font-size:18px}
.am-av i{position:absolute;bottom:-1px;left:-1px;width:11px;height:11px;border-radius:50%;border:2px solid var(--card);background:var(--st)}
.am-cd b{font-size:13px;line-height:1.4;unicode-bidi:plaintext;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;text-align:start}
.am-cd small{font-size:11.5px;color:var(--muted);unicode-bidi:plaintext;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;text-align:start}
.am-cd .ft{grid-column:1/-1;display:flex;align-items:center;gap:6px;margin-top:6px}
.am-md{font:600 10.5px/1.6 Inter,system-ui,sans-serif;padding:0 6px;border-radius:5px;background:var(--chip);color:var(--fg);direction:ltr}
.bar{flex:1;height:5px;border-radius:9px;background:var(--chip);overflow:hidden}.bar i{display:block;height:100%;border-radius:9px;background:var(--bc,hsl(150 50% 42%))}
.am-hit{outline:2.5px solid hsl(45 95% 50%);outline-offset:2px}
.am-sel{box-shadow:0 0 0 2.5px var(--boss),0 6px 16px -6px rgba(0,0,0,.3)}
.am-dim{opacity:.35}
.am-tg{font:inherit;font-size:11px;margin-top:-9px;z-index:1;border:1px solid var(--line);background:var(--card);color:var(--muted);border-radius:999px;padding:0 9px;cursor:pointer;line-height:1.7}
.am-tg:hover{color:var(--fg)}
.am-mm,.am-mm ul{list-style:none;margin:0;padding:0}
.am-mm ul{position:relative;margin-right:22px}
.am-mm ul::before{content:"";position:absolute;right:-22px;top:50%;width:22px;border-top:1.5px solid var(--line)}
.am-mm li{position:relative;display:flex;align-items:center;padding:3px 22px 3px 0}
.am-mm>li{padding-right:0}
.am-mm ul>li::before{content:"";position:absolute;right:0;top:50%;width:22px;border-top:1.5px solid var(--line)}
.am-mm ul>li::after{content:"";position:absolute;right:0;top:0;bottom:0;border-right:1.5px solid var(--line)}
.am-mm ul>li:first-child::after{top:50%}
.am-mm ul>li:last-child::after{bottom:50%}
.am-mm ul>li:only-child::after{display:none}
.am-mn{font:inherit;font-size:12.5px;white-space:nowrap;display:inline-flex;align-items:center;gap:6px;border:1px solid var(--line);background:var(--card);color:inherit;border-radius:999px;padding:2px 10px 2px 4px;cursor:pointer}
.am-mn .am-av{width:20px;height:20px;font-size:8.5px;grid-row:auto;letter-spacing:0}
.am-mn.cat{padding:3px 12px;font-weight:600;border-color:var(--cc);background:color-mix(in srgb,var(--cc) 12%,var(--card))}
.am-mn.root{font-weight:800;background:var(--fg);color:var(--card);padding:5px 14px;border:0}
.am-tb{width:100%;border-collapse:collapse;font-size:13px}
.am-tb th{font-size:12px;color:var(--muted);font-weight:600;text-align:right;padding:6px 8px;border-bottom:1px solid var(--line);cursor:pointer;white-space:nowrap;position:sticky;top:-18px;background:var(--card)}
.am-tb td{padding:6px 8px;border-bottom:1px solid var(--line);vertical-align:middle}
.am-tb tr[data-s]{cursor:pointer}.am-tb tr[data-s]:hover td{background:var(--chip)}
.am-tb .nm{display:flex;align-items:center;gap:8px}.am-tb .nm .am-av{width:26px;height:26px;font-size:10px;grid-row:auto}
.am-tb .nm span{display:grid;line-height:1.4}.am-tb .nm small{color:var(--muted);font-size:11.5px;unicode-bidi:plaintext}
.am-tb .bar{min-width:60px}
.am-drw{background:var(--card);border:1px solid var(--line);border-radius:12px;padding:14px;display:grid;gap:12px;align-content:start;position:sticky;top:60px}
.am-drw .top{display:flex;gap:12px;align-items:center}
.am-drw .top b{display:block;font-size:15px;unicode-bidi:plaintext}
.am-drw .x{margin-inline-start:auto;align-self:start;font:inherit;border:0;background:transparent;color:var(--muted);cursor:pointer;font-size:18px;line-height:1}
.am-drw dl{display:grid;grid-template-columns:auto 1fr;gap:4px 10px;margin:0;font-size:13px}
.am-drw dt{color:var(--muted)}.am-drw dd{margin:0;min-width:0}
.am-drw h4{margin:0;font-size:12px;color:var(--muted);font-weight:600}
.am-pl{display:flex;flex-wrap:wrap;gap:5px}
.am-pl span,.am-pl button{font:inherit;font-size:12px;background:var(--chip);border:0;color:inherit;border-radius:6px;padding:1px 8px}
.am-pl button{cursor:pointer;display:inline-flex;align-items:center;gap:5px}.am-pl button .am-av{width:18px;height:18px;font-size:8px;grid-row:auto;letter-spacing:0}
.am-pl .sk{direction:ltr}
.am-st{display:inline-flex;align-items:center;gap:5px;font-size:12px}.am-st::before{content:"";width:8px;height:8px;border-radius:50%;background:var(--st)}
.am-ft{display:flex;justify-content:space-between;flex-wrap:wrap;gap:6px}
.am-drw[hidden]{display:none}
.am-body.has .am-tb .opt{display:none}
@media (max-width:560px){.am-tb .opt,.am-tb td:nth-child(5) .bar,.am-tb td:last-child .bar{display:none}}
.am-tg{margin-bottom:-9px;position:relative}
.am-oc li>.am-cd+ul,.am-oc li>.am-tg+ul,.am-oc li>.am-tg+.am-stk{margin-top:0}
.am-stk{list-style:none;margin:0;padding:20px 0 0;display:flex;flex-direction:column;align-items:center;gap:10px;position:relative}
.am-stk::before{content:"";position:absolute;top:0;bottom:24px;left:50%;border-left:1.5px solid var(--line)}
.am-stk>li{position:relative;padding:0}
.am-dep{position:relative;border:1.5px dashed color-mix(in srgb,var(--cc) 55%,transparent);background:color-mix(in srgb,var(--cc) 7%,transparent);border-radius:14px;padding:26px 8px 10px;display:flex;flex-direction:column;align-items:center}
.am-dep>.lb{position:absolute;top:5px;right:10px;font-size:11.5px;font-weight:700;color:color-mix(in srgb,var(--cc) 75%,var(--fg));white-space:nowrap}
.am-oc .am-sub{padding-top:0}
.am-oc .am-sub::before{display:none}
.am-oc .am-sub>li{padding-top:0}
.am-oc .am-sub>li::before,.am-oc .am-sub>li::after{display:none}
.am-oc .am-sub{gap:6px}
.am-no{position:absolute;top:-9px;left:-7px;min-width:20px;height:20px;padding:0 5px;border-radius:10px;background:var(--boss);color:#fff;font:700 11px/20px Inter,system-ui,sans-serif;text-align:center;z-index:2;box-shadow:0 0 0 2px var(--card)}
.am-mn .am-no{position:static;box-shadow:none;margin-inline-start:4px}
.am-wfon{box-shadow:0 0 0 2px hsl(150 55% 42%),0 6px 16px -6px rgba(0,0,0,.3)}
.am-mo{font:600 10px/1.6 var(--body);padding:0 5px;border-radius:5px;color:var(--mo);background:color-mix(in srgb,var(--mo) 13%,transparent);white-space:nowrap}
.am-ir{margin-inline-end:3px}
.am-wfbar{display:flex;flex-wrap:wrap;gap:8px;align-items:center}
.am-wfbar label{display:flex;align-items:center;gap:6px;font-size:13px;flex:1 1 260px;min-width:0}
.am-wfbar select{font:inherit;font-size:13px;padding:4px 8px;border:1px solid var(--line);border-radius:9px;background:var(--card);color:var(--fg);flex:1;min-width:0}
.am-irb{font:inherit;font-size:13px;border:1px solid var(--line);background:var(--card);color:inherit;border-radius:999px;padding:3px 12px;cursor:pointer}
.am-irb[aria-pressed=true]{border-color:hsl(150 50% 40%);background:color-mix(in srgb,hsl(150 50% 40%) 12%,var(--card));font-weight:600}
.am-wf{background:var(--card);border:1px solid var(--line);border-radius:12px;padding:12px;display:grid;gap:10px}
.am-wf .hd{display:flex;flex-wrap:wrap;gap:4px 12px;align-items:baseline}
.am-path{list-style:none;margin:0;padding:0;display:flex;flex-wrap:wrap;gap:8px 4px;align-items:center}
.am-path li{display:flex;align-items:center;gap:6px;position:relative}
.am-path li+li::before{content:"←";color:var(--muted);margin-inline:2px 4px}
.am-path .no{display:grid;place-items:center;width:22px;height:22px;border-radius:50%;background:var(--cc,var(--muted));color:#fff;font:700 11px/1 Inter,system-ui,sans-serif;flex:none}
.am-path button{font:inherit;display:flex;align-items:center;gap:6px;border:1px solid var(--line);background:var(--bg);color:inherit;border-radius:10px;padding:3px 10px 3px 4px;cursor:pointer;text-align:start}
.am-path button .am-av{width:24px;height:24px;font-size:9px;grid-row:auto}.am-path button .am-av i{display:none}
.am-path button span{display:grid;line-height:1.35}.am-path b{font-size:12.5px}.am-path small{font-size:11px;color:var(--muted)}
.am-path .skip{opacity:.5}.am-path .skip>span:last-child{display:grid;line-height:1.35;font-size:12px}
.am-path .gt{font-style:normal;font-size:10.5px;color:hsl(0 65% 50%);border:1px solid currentColor;border-radius:5px;padding:0 4px}
.am-cd b .am-ir{font-size:11px}
.am-wf[hidden]{display:none}
.am-deps{position:relative;border:1.5px solid var(--line);border-radius:16px;padding:28px 12px 12px;background:color-mix(in srgb,var(--card) 60%,transparent)}
.am-deps>.lb{position:absolute;top:6px;right:14px;font-size:12px;font-weight:700;color:var(--muted)}
.am-deps .gr{display:grid;grid-template-columns:repeat(4,auto);gap:12px;align-items:start;justify-content:center}
.am-deps .am-dep{min-width:204px}
.am-lk path{fill:none;stroke-width:1.4}.am-lk marker path{stroke:none}
path.am-lk-wf{stroke:hsl(150 55% 40%);fill:none}marker path.am-lk-wf{fill:hsl(150 55% 40%)}
path.am-lk-in{stroke:hsl(215 70% 55%);stroke-dasharray:4 3;fill:none}marker path.am-lk-in{fill:hsl(215 70% 55%)}
path.am-lk-out{stroke:hsl(265 60% 58%);fill:none}marker path.am-lk-out{fill:hsl(265 60% 58%)}
/* v5.2: باز شدن عمودی — دپارتمان‌ها زیر هم، ایجنت‌ها زیر هم */
.am-deps .gr{grid-template-columns:minmax(0,1fr)!important;justify-items:center}
.am-deps .am-dep{width:min(100%,520px)}
.am-oc .am-sub{flex-direction:column;align-items:center}
.am-dep .am-oc ul{flex-direction:column;align-items:center}
/* v5.6: تب موکاپ تمام‌عرض و تمام‌ارتفاع */
.wrap:has(#p-mock:not([hidden])){max-width:none;padding-inline:max(12px,env(safe-area-inset-left,0px))}
#p-mock .pcw{margin-block:6px}
#p-mock .am-view{max-height:none;height:calc(100vh - 120px);min-height:560px}
#p-mock .am-body.has{grid-template-columns:minmax(0,1fr) 320px}
/* v5.7: چارت = بوم گستردهٔ نقشه؛ کشیدن برای جابه‌جایی، Ctrl+چرخ برای زوم */
#p-mock .am-view{height:calc(100vh - 70px);cursor:grab;background-size:22px 22px}
#p-mock .am-view.drag{cursor:grabbing;user-select:none}
#p-mock .pcs{display:none}#p-mock .pcw{grid-template-columns:minmax(0,1fr)}
#p-mock .am-bar{position:sticky;top:44px;z-index:6;background:color-mix(in srgb,var(--bg) 88%,transparent);backdrop-filter:blur(6px);padding:6px;border-radius:12px}
/* v5.8: نوار ابزار شناور روی خود نقشه (مثل ابزارهای تجاری) */
.am-stage{position:relative;min-width:0}
#p-mock .am-stage>.am-bar{position:absolute;top:10px;right:10px;left:10px;z-index:6;pointer-events:none;background:none;backdrop-filter:none;padding:0}
#p-mock .am-stage>.am-bar>*{pointer-events:auto;box-shadow:0 4px 14px -6px rgba(0,0,0,.3);backdrop-filter:blur(6px)}
#p-mock .am-stage>.am-bar .am-seg,#p-mock .am-stage>.am-bar .am-zoom{background:color-mix(in srgb,var(--card) 90%,transparent)}
#p-mock .am-stage>.am-bar .am-srch{flex:0 1 280px}
#p-mock .am-stage>.am-bar .am-zoom{margin-inline-start:auto}
#p-mock .am-view{padding-top:64px}
@media (max-width:700px){#p-mock .am-view{padding-top:110px}}
/* v5.9: کارت دستورالعمل ایجنت (Role Canvas: SIPOC + چراغ اختیار + قانون گیر کردن + سلامت) */
.in-bk{position:fixed;inset:0;z-index:50;background:rgba(10,12,18,.45);display:grid;place-items:center;padding:16px}
.in-bk[hidden]{display:none}
.in-cv{background:var(--bg);color:var(--fg);border-radius:16px;max-width:980px;width:100%;max-height:92vh;overflow:auto;padding:18px;display:grid;gap:14px;box-shadow:0 30px 60px -20px rgba(0,0,0,.5)}
.in-hd{display:flex;gap:12px;align-items:center}.in-hd b{font-size:17px}.in-hd .x{margin-inline-start:auto;font:inherit;font-size:22px;border:0;background:none;color:var(--muted);cursor:pointer}
.in-tabs{display:inline-flex;background:var(--chip);border-radius:9px;padding:2px;gap:2px;justify-self:start}
.in-tabs button{font:inherit;font-size:13px;border:0;background:none;color:var(--muted);padding:3px 12px;border-radius:7px;cursor:pointer}.in-tabs button[aria-pressed=true]{background:var(--card);color:var(--fg);font-weight:600}
.in-sp{display:grid;grid-template-columns:1fr auto 1.4fr auto 1fr;gap:8px;align-items:stretch}
.in-col{background:var(--card);border:1px solid var(--line);border-radius:12px;padding:10px;display:grid;gap:6px;align-content:start;min-width:0}
.in-col h4{margin:0;font-size:12px;color:var(--muted)}.in-col.me{border:2px solid var(--cc)}
.in-ar{align-self:center;color:var(--muted);font-size:20px}
.in-col ol{margin:0;padding-inline-start:18px;font-size:13px;line-height:1.7}
.in-p{font-size:12px;background:var(--chip);border-radius:6px;padding:1px 8px;display:inline-block;margin:1px}
.in-row{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:8px}
.in-l{border-radius:12px;padding:10px;display:grid;gap:4px;align-content:start;font-size:13px;border:1px solid var(--line);background:var(--card)}
.in-l b{display:flex;align-items:center;gap:6px}.in-l b::before{content:"";width:12px;height:12px;border-radius:50%;background:var(--lc)}
.in-l.on{box-shadow:inset 0 0 0 2px var(--lc)}
.in-st{display:flex;flex-wrap:wrap;gap:6px;align-items:center;font-size:13px}.in-st span{background:var(--card);border:1px solid var(--line);border-radius:10px;padding:4px 10px}.in-st i{font-style:normal;color:var(--muted)}
.in-hl{display:grid;grid-template-columns:repeat(auto-fill,minmax(210px,1fr));gap:4px 12px;font-size:12.5px}
.in-hl .ok::before{content:"✓ ";color:hsl(150 55% 38%)}.in-hl .no::before{content:"✗ ";color:hsl(0 65% 50%)}
.in-md{white-space:pre-wrap;direction:rtl;font:13px/1.8 var(--body);background:var(--card);border:1px solid var(--line);border-radius:12px;padding:12px;margin:0}
.in-btn{font:inherit;font-size:13px;border:1px solid var(--boss);color:var(--boss);background:var(--card);border-radius:9px;padding:4px 12px;cursor:pointer}
@media (max-width:760px){.in-sp,.in-row{grid-template-columns:minmax(0,1fr)}.in-ar{justify-self:center;transform:rotate(-90deg)}}
/* v6.1: فلوچارت دستورالعمل (شکل‌های BPMN، گره‌های کارتی مثل n8n) */
.fc{display:flex;flex-direction:column;align-items:center;gap:0;padding:8px 0}
.fc .ln{width:2px;height:18px;background:var(--muted);position:relative}
.fc .ln::after{content:"";position:absolute;bottom:-1px;left:-4px;border:5px solid transparent;border-top-color:var(--muted);border-bottom:0}
.fc .ev{width:54px;height:54px;border-radius:50%;display:grid;place-items:center;font-size:11px;text-align:center;line-height:1.3;border:2px solid hsl(150 55% 40%);background:var(--card)}
.fc .ev.end{border:4px solid hsl(0 0% 35%)}
.fc .tk{min-width:240px;max-width:420px;border:1px solid var(--line);border-inline-start:4px solid var(--cc,var(--boss));background:var(--card);border-radius:10px;padding:6px 12px;font-size:13px;display:flex;gap:8px;align-items:center;box-shadow:0 2px 6px -3px rgba(0,0,0,.2)}
.fc .tk i{font-style:normal;font-size:11px;color:var(--muted);margin-inline-start:auto;white-space:nowrap}
.fc .tk.gate{border-inline-start-color:hsl(0 65% 50%)}
.fc .gw{display:grid;grid-template-columns:1fr auto 1fr;align-items:center;gap:10px;width:min(100%,640px)}
.fc .dm{width:58px;height:58px;transform:rotate(45deg);border:2px solid hsl(38 90% 48%);background:var(--card);display:grid;place-items:center;justify-self:center}
.fc .dm span{transform:rotate(-45deg);font-size:18px;font-weight:700;color:hsl(38 90% 40%)}
.fc .q{grid-column:1/-1;text-align:center;font-size:12.5px;font-weight:600;margin-top:4px}
.fc .br{font-size:12px;border:1px dashed var(--line);border-radius:10px;padding:6px 10px;background:var(--card)}
.fc .br b{display:block;font-size:11px;color:var(--muted)}
.fc .br.no{justify-self:start}.fc .br.yes{justify-self:end}
.fc-lg{display:flex;flex-wrap:wrap;gap:12px;font-size:11.5px;color:var(--muted);justify-content:center}
.fsv .fb{fill:var(--card);stroke:var(--line);stroke-width:1.2}.fsv .fbg{stroke:hsl(0 65% 50%);stroke-width:2}.fsv .fbx{stroke:hsl(0 65% 50%);stroke-dasharray:4 3}
.fsv .fd{fill:var(--card);stroke:hsl(38 90% 48%);stroke-width:2}.fsv .fe{fill:var(--card);stroke:hsl(150 55% 40%);stroke-width:2}.fsv .fe2{fill:var(--card);stroke:var(--fg);stroke-width:4}
.fsv .fa{fill:none;stroke:var(--muted);stroke-width:1.6}.fsv .fa.no{stroke:#e8590c;stroke-dasharray:6 5}
/* v6.3 ایده از بوم استودیو */
.am-cur{outline:3px solid hsl(150 60% 42%);outline-offset:3px;box-shadow:0 0 0 8px color-mix(in srgb,hsl(150 60% 42%) 18%,transparent)}
.st-bar{display:flex;flex-wrap:wrap;gap:8px;align-items:center;font-size:13px;border-top:1px solid var(--line);padding-top:8px}.st-bar span{flex:1;min-width:180px}
.ck{width:min(620px,100%);background:var(--card);border:1px solid var(--line);border-radius:14px;overflow:hidden;align-self:start;margin-top:10vh}
.ck input{width:100%;box-sizing:border-box;border:0;border-bottom:1px solid var(--line);background:transparent;color:var(--fg);font:inherit;font-size:16px;padding:14px 16px;outline:none}
#ck-ls{max-height:55vh;overflow:auto;padding:6px}#ck-ls .gh{font-size:11px;color:var(--muted);padding:6px 10px 2px}#ck-ls .it{padding:7px 10px;border-radius:8px;cursor:pointer;font-size:13.5px}#ck-ls .it.on,#ck-ls .it:hover{background:var(--chip)}
.grd .gr{display:flex;justify-content:space-between;gap:8px;align-items:center;font-size:13px;padding:6px 0;border-bottom:1px solid var(--line)}.grd .gr.err span{color:hsl(0 65% 48%)}
/* v6.4 */
.mm-cv{position:absolute;left:12px;bottom:12px;width:180px;height:115px;z-index:6;background:var(--card);border:1px solid var(--line);border-radius:10px;box-shadow:0 4px 14px -6px rgba(0,0,0,.3);cursor:pointer}
@media (max-width:700px){.mm-cv{display:none}}
.va-off{opacity:.15!important;filter:grayscale(1)}.va-me{outline:3px solid hsl(150 60% 42%);outline-offset:3px}
.va-bn{position:absolute;left:50%;transform:translateX(-50%);bottom:14px;z-index:7;background:var(--fg);color:var(--card);border-radius:12px;padding:6px 10px;font-size:13px;display:flex;gap:8px;align-items:center;max-width:calc(100% - 220px)}.va-bn .am-btn{color:var(--fg)}
.dt-bar{display:flex;gap:2px;border-bottom:1px solid var(--line);position:sticky;top:0;background:var(--card);z-index:1}
.dt-bar button{font:inherit;font-size:12.5px;border:0;background:none;color:var(--muted);border-bottom:2px solid transparent;padding:6px 10px;cursor:pointer}.dt-bar button[aria-pressed=true]{color:var(--fg);font-weight:700;border-bottom-color:var(--boss)}

